// Generated by cpp-anything app front-door for a server: this binary owns the port
// and forwards every request to the original, which it starts on a private port.
#include <arpa/inet.h>
#include <netinet/in.h>
#include <signal.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>

#include <cerrno>
#include <cctype>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>

namespace {

std::vector<std::string> original_command() {
  return {"python3", "/mnt/data/Projects/OpenSource/cpp-anything/examples/http-app/server.py"};
}

int free_port() {
  const int fd = ::socket(AF_INET, SOCK_STREAM, 0);
  if (fd < 0) return 0;
  sockaddr_in address{};
  address.sin_family = AF_INET;
  address.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
  address.sin_port = 0;
  if (::bind(fd, reinterpret_cast<sockaddr*>(&address), sizeof address) != 0) {
    ::close(fd);
    return 0;
  }
  socklen_t length = sizeof address;
  if (::getsockname(fd, reinterpret_cast<sockaddr*>(&address), &length) != 0) {
    ::close(fd);
    return 0;
  }
  const int port = ntohs(address.sin_port);
  ::close(fd);
  return port;
}

bool wait_for_port(int port) {
  for (int attempt = 0; attempt < 200; ++attempt) {
    const int fd = ::socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) return false;
    sockaddr_in address{};
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    address.sin_port = htons(static_cast<uint16_t>(port));
    const bool ok = ::connect(fd, reinterpret_cast<sockaddr*>(&address), sizeof address) == 0;
    ::close(fd);
    if (ok) return true;
    ::usleep(50 * 1000);
  }
  return false;
}

pid_t start_original(int port) {
  const pid_t child = ::fork();
  if (child != 0) return child;
  std::string port_text = std::to_string(port);
  ::setenv("PORT", port_text.c_str(), 1);
  std::vector<std::string> words = original_command();
  std::vector<char*> exec;
  for (auto& word : words) exec.push_back(word.data());
  exec.push_back(nullptr);
  ::execvp(exec[0], exec.data());
  std::perror("cppan front door: cannot start the original");
  ::_exit(127);
}

void log_fallback() {
  const char* path = std::getenv("CPPAN_FALLBACK_LOG");
  if (path == nullptr || *path == '\0') return;
  if (FILE* file = std::fopen(path, "a")) {
    std::fprintf(file, "original\n");
    std::fclose(file);
  }
}

std::string read_request(int fd) {
  std::string data;
  char buffer[8192];
  size_t header_end = std::string::npos;
  size_t content_length = 0;
  while (true) {
    const ssize_t got = ::read(fd, buffer, sizeof buffer);
    if (got <= 0) break;
    data.append(buffer, static_cast<size_t>(got));
    if (header_end == std::string::npos) {
      header_end = data.find("\r\n\r\n");
      if (header_end != std::string::npos) {
        std::string head = data.substr(0, header_end);
        for (auto& ch : head) ch = static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));
        const size_t at = head.find("content-length:");
        if (at != std::string::npos) {
          content_length = static_cast<size_t>(std::strtoul(head.c_str() + at + 15, nullptr, 10));
        }
      }
    }
    if (header_end != std::string::npos && data.size() >= header_end + 4 + content_length) break;
  }
  return data;
}

void relay(int client, int port) {
  const int upstream = ::socket(AF_INET, SOCK_STREAM, 0);
  if (upstream < 0) return;
  sockaddr_in address{};
  address.sin_family = AF_INET;
  address.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
  address.sin_port = htons(static_cast<uint16_t>(port));
  if (::connect(upstream, reinterpret_cast<sockaddr*>(&address), sizeof address) != 0) {
    ::close(upstream);
    return;
  }
  const std::string request = read_request(client);
  if (request.empty()) {
    ::close(upstream);
    return;
  }
  size_t sent = 0;
  while (sent < request.size()) {
    const ssize_t wrote = ::write(upstream, request.data() + sent, request.size() - sent);
    if (wrote <= 0) break;
    sent += static_cast<size_t>(wrote);
  }
  char buffer[8192];
  while (true) {
    const ssize_t got = ::read(upstream, buffer, sizeof buffer);
    if (got <= 0) break;
    size_t sent_back = 0;
    while (sent_back < static_cast<size_t>(got)) {
      const ssize_t wrote = ::write(client, buffer + sent_back, static_cast<size_t>(got) - sent_back);
      if (wrote <= 0) break;
      sent_back += static_cast<size_t>(wrote);
    }
  }
  ::close(upstream);
}

}  // namespace

int main() {
  const char* port_text = std::getenv("PORT");
  if (port_text == nullptr) {
    std::fprintf(stderr, "cppan_app: set PORT to the port to listen on\n");
    return 2;
  }
  const int public_port = std::atoi(port_text);
  const int internal_port = free_port();
  if (internal_port == 0) {
    std::fprintf(stderr, "cppan_app: cannot find a private port for the original\n");
    return 2;
  }
  const pid_t child = start_original(internal_port);
  if (child < 0 || !wait_for_port(internal_port)) {
    std::fprintf(stderr, "cppan_app: the original did not start on %d\n", internal_port);
    return 2;
  }

  const int listener = ::socket(AF_INET, SOCK_STREAM, 0);
  if (listener < 0) {
    std::perror("socket");
    return 2;
  }
  int reuse = 1;
  ::setsockopt(listener, SOL_SOCKET, SO_REUSEADDR, &reuse, sizeof reuse);
  sockaddr_in address{};
  address.sin_family = AF_INET;
  address.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
  address.sin_port = htons(static_cast<uint16_t>(public_port));
  if (::bind(listener, reinterpret_cast<sockaddr*>(&address), sizeof address) != 0) {
    std::perror("bind");
    return 2;
  }
  if (::listen(listener, 64) != 0) {
    std::perror("listen");
    return 2;
  }
  std::fprintf(stderr, "cppan_app: %d -> original on %d\n", public_port, internal_port);
  while (true) {
    const int client = ::accept(listener, nullptr, nullptr);
    if (client < 0) {
      if (errno == EINTR) continue;
      break;
    }
    log_fallback();
    relay(client, internal_port);
    ::close(client);
  }
  ::kill(child, SIGTERM);
  return 0;
}
